window.BEHPARVAR_MBTI_BANK={"version":"2026-11-20-plain-language","items":[["EI","E","در شروع همکاری با تیمی ناآشنا، معمولاً با گفت‌وگو با اعضا وارد جریان کار می‌شوم.","در شروع همکاری با تیمی ناآشنا، معمولاً ابتدا محیط و شیوه کار را مشاهده می‌کنم و بعد وارد گفت‌وگو می‌شوم."],["SN","S","برای فهم موضوع جدید، ترجیح می‌دهم اول یک نمونه ملموس و جزئیات واقعی ببینم.","برای فهم موضوع جدید، ترجیح می‌دهم اول مفهوم کلی و ارتباط آن با موضوعات دیگر را درک کنم."],["TF","T","برای انتخاب میان دو گزینه کاری، دلایل روشن و نتیجه‌های قابل‌سنجش هر گزینه را مبنای تصمیم قرار می‌دهم.","برای انتخاب میان دو گزینه کاری، ارزش‌های مرتبط و اثر تصمیم بر افراد درگیر را بیشتر مبنا قرار می‌دهم."],["JP","J","برای هفته کاری، داشتن برنامه و موعدهای روشن از ابتدا را ترجیح می‌دهم.","برای هفته کاری، بازگذاشتن زمان‌ها برای سازگاری با اتفاق‌های تازه را ترجیح می‌دهم."],["EI","I","پس از چند ساعت گفت‌وگو و جلسه، برای بازیابی انرژی معمولاً به خلوت کوتاه نیاز دارم.","پس از چند ساعت گفت‌وگو و جلسه، معمولاً با ادامه تعامل با دیگران سرحال‌تر می‌شوم."],["SN","N","در بررسی یک گزارش، سریع‌تر به ارتباط میان داده‌ها و الگوهای احتمالی توجه می‌کنم.","در بررسی یک گزارش، سریع‌تر به اعداد، رویدادهای ثبت‌شده و جزئیات قابل‌بررسی توجه می‌کنم."],["TF","F","در بازخورد به همکار، معمولاً ابتدا شرایط او و اثر حرفم بر رابطه کاری را در نظر می‌گیرم.","در بازخورد به همکار، معمولاً ابتدا رفتار قابل‌مشاهده و معیار عملکرد را روشن می‌کنم."],["JP","P","پیش از انتخاب راه‌حل، معمولاً مایلم گزینه‌ها مدتی باز بمانند تا اطلاعات بیشتری برسد.","پیش از انتخاب راه‌حل، معمولاً ترجیح می‌دهم پس از اطلاعات کافی، زودتر به تصمیم مشخص برسیم."],["EI","E","وقتی ایده هنوز کامل نشده است، معمولاً با بیان آن در گفت‌وگو بهتر فکر می‌کنم.","وقتی ایده هنوز کامل نشده است، معمولاً ابتدا آن را در ذهن یا روی کاغذ پرورش می‌دهم."],["SN","S","در یادآوری تجربه یک پروژه، معمولاً اتفاق‌های مشخص و جزئیات آن را به خاطر می‌آورم.","در یادآوری تجربه یک پروژه، معمولاً معنای کلی یا درسی را که از آن گرفته‌ام به خاطر می‌آورم."],["TF","T","برای تقسیم منابع محدود، ابتدا معیارهای روشن اولویت‌بندی و اثربخشی را ملاک قرار می‌دهم.","برای تقسیم منابع محدود، ابتدا نیازهای متفاوت افراد و پیامد تخصیص برای آن‌ها را ملاک قرار می‌دهم."],["JP","J","برای یک جلسه مشترک، ترجیح می‌دهم زمان شروع و پایان از قبل قطعی باشد.","برای یک جلسه مشترک، ترجیح می‌دهم زمان‌بندی تا حدی قابل تغییر باقی بماند."],["EI","I","وقتی پیامی درباره موضوع پیچیده دریافت می‌کنم، معمولاً ترجیح می‌دهم پیش از پاسخ کمی فکر کنم.","وقتی پیامی درباره موضوع پیچیده دریافت می‌کنم، معمولاً ترجیح می‌دهم همان ابتدا با تماس یا گفت‌وگو مسئله را باز کنم."],["SN","N","از نشانه‌های پراکنده، معمولاً زودتر احتمال‌ها و برداشت‌های ضمنی را در ذهن شکل می‌دهم.","از نشانه‌های پراکنده، معمولاً ابتدا واقعیت‌های هر نشانه را جداگانه بررسی می‌کنم."],["TF","F","در حل اختلاف همکاران، بیشتر به حفظ احترام، ارزش‌ها و اثر تصمیم بر افراد توجه می‌کنم.","در حل اختلاف همکاران، بیشتر به قوانین روشن و شواهد مربوط به هر طرف توجه می‌کنم."],["JP","P","وقتی اطلاعات تصمیم هنوز کامل نیست، ترجیح می‌دهم امکان بازگشت و بازنگری را حفظ کنیم.","وقتی اطلاعات تصمیم هنوز کامل نیست، ترجیح می‌دهم در زمان مقرر با داده‌های موجود جمع‌بندی کنیم."],["EI","E","در فعالیت‌های کاری، معمولاً در تعامل مستقیم با محیط و افراد احساس مشارکت بیشتری می‌کنم.","در فعالیت‌های کاری، معمولاً با تمرکز مستقل و پرداختن عمیق به موضوع احساس مشارکت بیشتری می‌کنم."],["SN","S","برای شناسایی علت یک خطا، ابتدا مشاهدات مستقیم و شواهد موجود را جمع می‌کنم.","برای شناسایی علت یک خطا، ابتدا فرضیه‌هایی درباره ارتباط عوامل و الگوهای پنهان می‌سازم."],["TF","T","در ارزیابی یک پیشنهاد، منطق استدلال و شواهد پشتیبان برایم قانع‌کننده‌تر است.","در ارزیابی یک پیشنهاد، هماهنگی آن با ارزش‌های مهم و پیامدهای انسانی برایم قانع‌کننده‌تر است."],["JP","J","در آغاز کار گروهی، روشن‌بودن نقش‌ها و مسئولیت‌ها را از ابتدا ترجیح می‌دهم.","در آغاز کار گروهی، ترجیح می‌دهم نقش‌ها با پیشرفت کار و شناخت توانایی‌ها تنظیم شوند."],["EI","I","برای گفت‌وگویی مهم، معمولاً تعامل محدودتر و عمیق با یک یا دو نفر را ترجیح می‌دهم.","برای گفت‌وگویی مهم، معمولاً تبادل نظر با افراد متنوع‌تر را ترجیح می‌دهم."],["SN","N","وقتی پیشنهادی ناتمام می‌شنوم، معمولاً کاربردها و امکان‌های تازه‌اش را در ذهن گسترش می‌دهم.","وقتی پیشنهادی ناتمام می‌شنوم، معمولاً می‌پرسم دقیقاً چه کاری و با چه امکاناتی قابل اجراست."],["TF","F","در تغییر یک رویه، پذیرش و احساس عدالت از نگاه افراد درگیر برایم مهم‌تر است.","در تغییر یک رویه، سازگاری تصمیم با قواعد عمومی و استدلال منطقی برایم مهم‌تر است."],["JP","P","وقتی برنامه روزانه ناگهان به هم می‌ریزد، بازچینی آزادانه کارها را ترجیح می‌دهم.","وقتی برنامه روزانه ناگهان به هم می‌ریزد، بازگشت سریع به اولویت‌های برنامه قبلی را ترجیح می‌دهم."],["EI","E","در آشنایی با همکاران چند واحد، ترجیح می‌دهم ارتباط‌های کاری متنوع و تازه بسازم.","در آشنایی با همکاران چند واحد، ترجیح می‌دهم چند رابطه کاری محدود ولی عمیق بسازم."],["SN","S","هنگام توضیح یک مهارت، ترجیح می‌دهم از مراحل عملی و مشاهده‌شدنی آغاز کنم.","هنگام توضیح یک مهارت، ترجیح می‌دهم از اصول و الگوی مفهومی پشت آن آغاز کنم."],["TF","T","در واگذاری یک فرصت به همکار، بیشتر به معیارهای مشترک شایستگی و سابقه عملکرد تکیه می‌کنم.","در واگذاری یک فرصت به همکار، بیشتر به ظرفیت رشد فرد و شرایط خاص او توجه می‌کنم."],["JP","J","وقتی تصمیمی تصویب شده است، ترجیح می‌دهم تمرکز تیم روی پیاده‌سازی همان تصمیم باشد.","وقتی تصمیمی تصویب شده است، ترجیح می‌دهم امکان تغییر تصمیم با اطلاعات تازه باز بماند."],["EI","I","پس از شنیدن نقدی جدی، معمولاً آن را ابتدا در ذهن خودم مرور می‌کنم.","پس از شنیدن نقدی جدی، معمولاً با گفت‌وگوی همان لحظه واکنش و برداشت خود را روشن می‌کنم."],["SN","N","در تشریح نتیجه یک کار، بیشتر روی الگوی آموخته‌شده و معنای کلی یافته‌ها تأکید می‌کنم.","در تشریح نتیجه یک کار، بیشتر روی شواهد دقیق و اتفاق‌های مشخص تأکید می‌کنم."],["TF","F","برای پاسخ به درخواست استثنایی یک همکار، شرایط فرد و ارزش‌های انسانی مرتبط را بیشتر در نظر می‌گیرم.","برای پاسخ به درخواست استثنایی یک همکار، یکسان‌بودن اصول و قابلیت دفاع از تصمیم را بیشتر در نظر می‌گیرم."],["JP","P","وقتی کاری تازه شروع می‌شود، ترجیح می‌دهم جزئیات روش را در مسیر تجربه و اصلاح کنم.","وقتی کاری تازه شروع می‌شود، ترجیح می‌دهم پیش از اقدام مسیر و مراحل اصلی روشن باشند."],["EI","E","در کارگاه تعاملی، معمولاً با مشارکت زبانی در بحث‌ها بهتر یاد می‌گیرم.","در کارگاه تعاملی، معمولاً با گوش‌دادن و تأمل فردی پیش از اظهار نظر بهتر یاد می‌گیرم."],["SN","S","برای بهبود فرایند، ترجیح می‌دهم ابتدا روش‌های آزموده‌شده و تجربه‌های مشابه را بررسی کنم.","برای بهبود فرایند، ترجیح می‌دهم ابتدا امکان بازتعریف روش و دیدن ارتباط تازه میان اجزا را بررسی کنم."],["TF","T","در گفت‌وگوی تصمیم‌گیری، مطرح‌کردن نقد منطقی را حتی اگر ناخوشایند باشد ضروری‌تر می‌دانم.","در گفت‌وگوی تصمیم‌گیری، توجه به اثر نحوه طرح نقد بر افراد را ضروری‌تر می‌دانم."],["JP","J","برای چند کار هم‌زمان، ترجیح می‌دهم اولویت‌ها را از ابتدا مرتب و دنبال کنم.","برای چند کار هم‌زمان، ترجیح می‌دهم اولویت‌ها را با جریان اتفاق‌ها تغییر دهم."],["EI","I","اگر در جلسه ناگهان از من نظری بخواهند، ترجیح می‌دهم چند لحظه برای صورت‌بندی پاسخ وقت بگیرم.","اگر در جلسه ناگهان از من نظری بخواهند، ترجیح می‌دهم با شروع صحبت، پاسخ را به‌تدریج روشن کنم."],["SN","N","وقتی موضوعی غیرمنتظره رخ می‌دهد، معمولاً به پیامدهای احتمالی و معنای پنهان آن توجه می‌کنم.","وقتی موضوعی غیرمنتظره رخ می‌دهد، معمولاً به آنچه واقعاً رخ داده و می‌توان مشاهده کرد توجه می‌کنم."],["TF","F","وقتی دو تصمیم از نظر فنی نزدیک‌اند، سازگاری با ارزش‌های سازمان و اثر بر افراد برایم تعیین‌کننده‌تر است.","وقتی دو تصمیم از نظر فنی نزدیک‌اند، منطق مقایسه و قابل دفاع بودن معیارها برایم تعیین‌کننده‌تر است."],["JP","P","با تغییر شرایط پروژه، ترجیح می‌دهم برنامه را بازبینی و انتخاب‌ها را دوباره باز کنم.","با تغییر شرایط پروژه، ترجیح می‌دهم ابتدا چارچوب توافق‌شده را حفظ و در همان چارچوب اقدام کنم."],["EI","E","در فهم محیط کار، معمولاً تجربه مستقیم و صحبت با افراد برایم محرک اصلی توجه است.","در فهم محیط کار، معمولاً تأمل مستقل بر مشاهدات و برداشت‌های خودم برایم محرک اصلی توجه است."],["SN","S","برای تصمیم امروز، معمولاً از تجربه‌های مشخص و قابل مقایسه گذشته شروع می‌کنم.","برای تصمیم امروز، معمولاً از احتمال‌های تازه‌ای شروع می‌کنم که هنوز در عمل آزموده نشده‌اند."],["TF","T","در اختلاف‌نظر حرفه‌ای، ابتدا استدلال طرف مقابل و شواهد مربوط را ارزیابی می‌کنم.","در اختلاف‌نظر حرفه‌ای، ابتدا دغدغه‌ها و ارزش‌هایی را که پشت دیدگاه طرف مقابل است درک می‌کنم."],["JP","J","در پایان یک جلسه، داشتن تصمیم، مسئول و موعد مشخص را ترجیح می‌دهم.","در پایان یک جلسه، بازماندن فرصت برای بررسی بیشتر و تکمیل گزینه‌ها را ترجیح می‌دهم."],["EI","I","در انجام کاری که مستقل هم ممکن است، ترجیح می‌دهم بخش اصلی آن را بدون وقفه پیش ببرم و بعد نتیجه را مطرح کنم.","در انجام کاری که مستقل هم ممکن است، ترجیح می‌دهم در طول کار چند بار با همکاران گفت‌وگو و تبادل نظر کنم."],["SN","N","وقتی چند نفر روایت‌های متفاوتی از یک مسئله دارند، معمولاً به دنبال الگوی مشترک و ارتباط میان روایت‌ها می‌گردم.","وقتی چند نفر روایت‌های متفاوتی از یک مسئله دارند، معمولاً ابتدا جزئیات قابل تأیید هر روایت را جداگانه بررسی می‌کنم."],["TF","F","وقتی ناچار به اعلام تصمیمی ناخوشایند هستم، بیشتر به حفظ احترام و پیامد انسانی آن توجه می‌کنم.","وقتی ناچار به اعلام تصمیمی ناخوشایند هستم، بیشتر به توضیح منطق تصمیم و یکسان‌بودن قاعده توجه می‌کنم."],["JP","P","هنگام روبه‌روشدن با مانع اجرایی، ترجیح می‌دهم روش انجام کار را آزادانه تغییر دهم.","هنگام روبه‌روشدن با مانع اجرایی، ترجیح می‌دهم تا حد ممکن مسیر و روش توافق‌شده را حفظ کنم."]],"contexts":["آغاز همکاری در یک تیم تازه","برخورد نخست با یک موضوع تازه","انتخاب میان دو گزینه دشوار","برنامه‌ریزی هفته کاری","بازیابی انرژی پس از نشست طولانی","خواندن گزارش عملکرد","بازخورد درباره عملکرد","تصمیم‌گیری میان چند راه‌حل","شکل‌دادن به یک ایده اولیه","مرور تجربه یک پروژه گذشته","تخصیص منابع محدود","هماهنگی زمان جلسه","پاسخ به یک درخواست پیچیده","مواجهه با نشانه‌های مبهم","رسیدگی به اختلاف دو همکار","مواجهه با اطلاعات ناکامل","انتخاب شیوه مشارکت در کار","بررسی علت یک خطای عملیاتی","شنیدن پیشنهاد یک همکار","تقسیم نقش در پروژه","انتخاب شکل گفت‌وگوی کاری","شنیدن یک پیشنهاد اولیه","بازنگری یک رویه کاری","اختلال در برنامه روزانه","گسترش شبکه ارتباطی در سازمان","توضیح یک مهارت به همکار","سپردن یک مسئولیت تازه","مرحله بعد از تصویب تصمیم","دریافت بازخورد مهم","ارائه نتیجه یک بررسی","رسیدگی به درخواست استثنایی","آغاز یک فعالیت جدید","یادگیری در یک کارگاه","بهبود یک فرایند جاافتاده","ارائه نقد در جلسه","مدیریت چند کار هم‌زمان","پاسخ‌دادن بدون آمادگی قبلی","مواجهه با یک رخداد غیرمنتظره","انتخاب میان دو راه‌حل نزدیک","تغییر شرایط حین اجرای پروژه","شناخت یک مسئله محیط کار","استفاده از تجربه برای تصمیم","اختلاف‌نظر در جلسه","جمع‌بندی جلسه","همکاری در یک کار نیمه‌مستقل","شنیدن روایت‌های متفاوت از یک مسئله","اعلام یک تصمیم ناخوشایند","بروز مانع در مسیر اجرا"],"examples":[["در روز اول به چند نفر سر می‌زنم و درباره کارشان سؤال می‌کنم.","ابتدا روند کار و وظایف را می‌خوانم، سپس با افراد گفت‌وگو می‌کنم."],["اول نمونه سفارش واقعی را بررسی می‌کنم.","اول می‌پرسم این مسئله با کدام فرایندهای دیگر ارتباط دارد."],["گزینه‌ها را بر اساس معیارهای اعلام‌شده مقایسه می‌کنم.","بررسی می‌کنم هر گزینه چه اثری بر افراد و ارزش‌های تیم دارد."],["برای بازدید و گزارش، زمان قطعی در تقویم می‌گذارم.","بازه‌های زمانی باز می‌گذارم تا در طول هفته آن‌ها را تنظیم کنم."],["بعد از جلسه مدتی در فضای آرام می‌مانم.","بعد از جلسه با همکاران به گفت‌وگوی غیررسمی ادامه می‌دهم."],["رابطه احتمالی میان خرابی و تغییر شیفت را جست‌وجو می‌کنم.","ابتدا تعداد خرابی، زمان و محل هر مورد را کنترل می‌کنم."],["قبل از بازخورد می‌پرسم چه محدودیتی داشته است.","ابتدا نمونه رفتار و فاصله آن از معیار را شرح می‌دهم."],["برای بررسی یک گزینه تازه فرصت کوتاهی پیشنهاد می‌کنم.","از تیم می‌خواهم گزینه منتخب را مشخص و اجرای آن را شروع کنیم."],["ایده خام را در گفت‌وگوی دو نفره مطرح می‌کنم.","پیش از مطرح‌کردن ایده، نکات اصلی را برای خودم یادداشت می‌کنم."],["به یاد می‌آورم دقیقاً چه رویدادی در کدام مرحله اتفاق افتاد.","به یاد می‌آورم الگوی اصلی مسئله چه بود و چه درسی داشت."],["بودجه را با معیار اثر و فوریت بین واحدها توزیع می‌کنم.","ابتدا می‌سنجم کاهش بودجه بر کدام افراد فشار بیشتری می‌آورد."],["زمان جلسه را مشخص می‌کنم و از همه تأیید می‌گیرم.","زمان جلسه را با توجه به نیازهای جدید جابه‌جا می‌کنم."],["ابتدا پیام را دوباره می‌خوانم و پاسخ را آماده می‌کنم.","تماس می‌گیرم تا با پرسش و پاسخ مسئله را روشن کنم."],["از چند علامت جزئی احتمال یک تغییر پنهان را مطرح می‌کنم.","هر علامت را با گزارش یا مشاهده مستقیم بررسی می‌کنم."],["از هر دو نفر درباره نگرانی‌ها و آنچه برایشان مهم است می‌پرسم.","ادعاها را با توافق‌ها و شواهد مشترک مقایسه می‌کنم."],["تصمیم آزمایشی می‌گیریم و زمان بازنگری می‌گذاریم.","در موعد توافق‌شده گزینه مناسب را انتخاب می‌کنیم."],["برای بررسی مسئله به میان همکاران و محیط اجرا می‌روم.","برای تحلیل مسئله زمانی بدون وقفه برای خودم در نظر می‌گیرم."],["ثبت‌های دستگاه و اتفاق‌های همان شیفت را کنترل می‌کنم.","احتمال ارتباط خطا با چند تغییر هم‌زمان را بررسی می‌کنم."],["می‌پرسم چه شواهدی از اثربخشی پیشنهاد داریم.","می‌پرسم این پیشنهاد برای کارکنان و مشتریان چه معنایی دارد."],["قبل از شروع، مسئول هر فعالیت را ثبت می‌کنیم.","پس از شروع، مسئولیت‌ها را متناسب با نیازهای تازه تنظیم می‌کنیم."],["ابتدا موضوع را با یک همکار به‌تفصیل مطرح می‌کنم.","موضوع را در جمعی با دیدگاه‌های مختلف به بحث می‌گذارم."],["چند کاربرد احتمالی را که هنوز مطرح نشده‌اند تصور می‌کنم.","می‌پرسم منابع و گام اجرایی پیشنهادی کدام‌اند."],["گفت‌وگو می‌کنم تا بدانم تغییر برای گروه‌ها چقدر منصفانه است.","بررسی می‌کنم رویه جدید برای همه موقعیت‌های مشابه سازگار اجرا شود."],["پس از یک درخواست فوری، ترتیب فعالیت‌ها را دوباره تنظیم می‌کنم.","پس از رسیدگی به فوریت، به فهرست اولیه برمی‌گردم."],["در نشست بین‌واحدی با افراد بیشتری ارتباط اولیه برقرار می‌کنم.","با دو نفر که موضوع مشترک داریم گفت‌وگوی مفصل‌تری شکل می‌دهم."],["ابتدا روش ثبت سفارش را قدم‌به‌قدم نشان می‌دهم.","ابتدا توضیح می‌دهم منطق جریان سفارش چگونه کار می‌کند."],["معیارهای لازم و عملکرد قبلی گزینه‌ها را می‌سنجم.","نیاز رشدی هر فرد و اثر فرصت بر انگیزه او را می‌سنجم."],["کارها را بر اساس تصمیم نهایی تقسیم می‌کنم.","در کنار اجرا، نقاط بازبینی تصمیم را باز نگه می‌دارم."],["زمانی برای اندیشیدن به نکات بازخورد درخواست می‌کنم.","همان‌جا پرسش می‌کنم و با گفت‌وگو نکات را باز می‌کنم."],["توضیح می‌دهم چه الگویی از چند رویداد به دست آمده است.","عددها و نمونه‌های مستند را به ترتیب ارائه می‌کنم."],["پیش از پاسخ درباره شرایط ویژه او صحبت می‌کنم.","ابتدا می‌سنجم آیا این استثنا با ضوابط مشترک سازگار است."],["با یک اجرای کوچک شروع می‌کنم و گام‌های بعد را تنظیم می‌کنم.","اول مراحل اصلی و نقاط کنترل را مشخص می‌کنم."],["در گفت‌وگو مثال می‌زنم و مفهوم را حین حرف‌زدن روشن می‌کنم.","یادداشت برمی‌دارم و پس از جمع‌بندی پرسشم را مطرح می‌کنم."],["می‌پرسم در دفعات قبلی چه راهی جواب داده است.","می‌پرسم اگر فرض قبلی را کنار بگذاریم چه الگوی دیگری ممکن است."],["تناقض‌های طرح را مستقیم و مستدل مطرح می‌کنم.","ابتدا شیوه بیان را طوری انتخاب می‌کنم که کرامت طرف مقابل حفظ شود."],["سه کار اصلی امروز را رتبه‌بندی می‌کنم و به ترتیب پیش می‌روم.","با رسیدن اطلاعات تازه تصمیم می‌گیرم کدام کار جلو بیفتد."],["می‌گویم چند لحظه فرصت بدهید تا نظرم را مرتب کنم.","با بیان اولین برداشت، در گفت‌وگو آن را دقیق‌تر می‌کنم."],["می‌پرسم این رخداد نشانه چه روند بزرگ‌تری می‌تواند باشد.","می‌پرسم دقیقاً کجا، چه زمانی و چه اتفاقی افتاده است."],["سراغ ارزش‌ها و میزان پذیرش تصمیم در تیم می‌روم.","معیارها را وزن‌دهی می‌کنم و استدلال مقایسه را روشن می‌سازم."],["با تیم درباره گزینه‌های تازه و اصلاح مسیر گفت‌وگو می‌کنم.","ابتدا بررسی می‌کنم چطور طبق برنامه مصوب ادامه دهیم."],["به واحد مربوط سر می‌زنم و گفت‌وگو را شروع می‌کنم.","مشاهداتم را کنار هم می‌گذارم و در سکوت تحلیل می‌کنم."],["به پرونده مشابه قبلی و نتیجه آن رجوع می‌کنم.","چند مسیر تازه را که قبلاً امتحان نشده‌اند تصور می‌کنم."],["درباره فرض‌ها و داده‌های پشت استدلال سؤال می‌کنم.","می‌پرسم چه نگرانی یا ارزشی باعث این موضع شده است."],["پیش از پایان، مسئول هر اقدام و زمان انجام را ثبت می‌کنم.","اگر اطلاعات کافی نباشد، موضوع را برای بررسی بیشتر باز می‌گذارم."],["ابتدا گزارش را مستقل آماده می‌کنم و سپس برای بررسی می‌فرستم.","حین تهیه گزارش چند بار با همکاران درباره یافته‌ها صحبت می‌کنم."],["از گفته‌های سه واحد، احتمال یک علت مشترک را بررسی می‌کنم.","زمان، محل و شواهد ثبت‌شده گفته‌های هر واحد را جداگانه تطبیق می‌دهم."],["ابتدا نگرانی فرد و شیوه حمایتی گفت‌وگو را در نظر می‌گیرم.","ابتدا مبنای تصمیم و معیار مشترک را روشن می‌کنم."],["با تیم روش متفاوتی را برای عبور از مانع امتحان می‌کنم.","ابتدا در چارچوب فرایند مصوب راه رفع مانع را پیدا می‌کنم."]]};
